public class InvoiceExporter {
    // Tạo một lần khi class được khởi tạo lúc startup (trên main, TCCL đúng), dùng chung: JAXBContext thread-safe và đắt
    private static final JAXBContext CONTEXT = newContext();

    // Thread của pool riêng nhận TCCL của thread tạo ra nó
    private final ExecutorService exportPool = Executors.newFixedThreadPool(4);

    private static JAXBContext newContext() {
        try {
            return JAXBContext.newInstance(Invoice.class);
        } catch (JAXBException e) {
            throw new ExceptionInInitializerError(e);
        }
    }

    static String toXml(Invoice invoice) {
        try {
            Marshaller m = CONTEXT.createMarshaller(); // Marshaller không thread-safe: mỗi lần một cái
            StringWriter out = new StringWriter();
            m.marshal(invoice, out);
            return out.toString();
        } catch (JAXBException e) {
            throw new IllegalStateException("export " + invoice.id, e);
        }
    }

    public List<String> exportAll(List<Invoice> invoices) {
        List<CompletableFuture<String>> jobs = invoices.stream()
                .map(inv -> CompletableFuture.supplyAsync(() -> toXml(inv), exportPool))
                .toList();
        return jobs.stream().map(CompletableFuture::join).toList();
    }
}
